INSERT INTO lab_result_item(
    id, report_id, item_code, item_name, value_num, value_text, unit,
    ref_low, ref_high, abnormal_flag,
    is_deleted, gmt_created, gmt_modified, gmt_deleted
) VALUES (
    #{id}, #{reportId}, #{itemCode}, #{itemName}, #{valueNum}, #{valueText}, #{unit},
    #{refLow}, #{refHigh}, #{abnormalFlag},
    #{isDeleted}, #{gmtCreated}, #{gmtModified}, #{gmtDeleted}
)

mapper.select:
SELECT i.item_code AS itemCode, i.value_num AS valueNum, i.unit AS unit, COALESCE(r.reported_at, r.sampled_at, i.gmt_created) AS recordedAt FROM lab_result_item i INNER JOIN lab_report r ON r.id = i.report_id AND r.is_deleted = 0 WHERE r.tenant_id = #{tenantId} AND r.people_id = #{peopleId} AND i.is_deleted = 0 AND i.value_num IS NOT NULL AND i.item_code IN
#{code}
ORDER BY COALESCE(r.reported_at, r.sampled_at, i.gmt_created) DESC
